  const accessoryResults = await evaluate(`(()=>{document.querySelectorAll('.tab')[3].click();return [...document.querySelectorAll('.item')].filter(b=>['Kawaii headphones','Star clips','Angel halo'].includes(b.getAttribute('aria-label'))).map(b=>{b.click();let k={'Kawaii headphones':'headphones','Star clips':'starclips','Angel halo':'halo'}[b.getAttribute('aria-label')];return [b.getAttribute('aria-label'),getComputedStyle(document.getElementById('acc-'+k)).display]})})()`);
