  const storage = await evaluate(`({saved:!!localStorage.getItem('petal-prism-look'), heart:document.querySelector('#heart').textContent})`);
  await send('Emulation.setDeviceMetricsOverride', { width: 375, height: 812, deviceScaleFactor: 1, mobile: true });
  await delay(200);
  const mobile = await evaluate(`({viewport:innerWidth, document:document.documentElement.scrollWidth, stage:Math.round(document.querySelector('.stage-card').getBoundingClientRect().height), studio:Math.round(document.querySelector('.studio-card').getBoundingClientRect().width), overflow:document.documentElement.scrollWidth>innerWidth})`);
